// CoreSwitches_AC.h// Copyright © 1985-2001 by Apple Computer. All rights reserved. /*	Change History		04/19/01	Add qTrainingWheels. 		03/01/01	Cosmetic. 		01/02/01	Update copyright.		12/22/00	Clarify comments for qNeedsAppearance and qEmulateStandardControls. 					Add qAppearance. 		12/04/00	Add qNeedsCarbonEvents. Make sure qDebug, qThreadDebug and 					qProjectBuilder are not left undefined. 		11/27/00	Change #if __POWERPC__ to #ifdef so it will work in Rez and DeRez. 		11/07/00	Added definition of qNavigation.		11/04/00	Require Appearance for all Mac platforms, not just PowerPC. 					Add qEmulateStandardControls and turn it off. 		10/30/00	[C] Set qProjectBuilder if __GNUC__.  Use this instead of __GNUC__					for now.		10/30/00	Move contents of ThreadSwitches into CoreSwitches. 		03/10/00	Include just ThreadSwitches_AC, not Threads_AC. That's because					Threads_AC pulls in MacTypes.h which breaks Rez. 					ThreadSwitches_AC had a #if that explicitly prevented it from					being included separately, but that's been taken out. 		03/06/00	Must include thread switches before any toolbox header that					includes Multiprocessing.h. 		02/22/00	[W] Added flag definitions for qWantsThreadManager, kAppName and kDocName.		12/07/99	Fixed definition of q68K since defined(qPowerPC) does not					mean (qPowerPC == 1) .		11/04/99	If qCarbon is not defined, define it as 0.		10/25/99	Carbon: For now, Tidyheap is disabled.		07/27/99	Removed qAllegro switch since Universal Interfaces 3.2 or greater					are now required.		03/24/99	Update copyright notice.		11/16/98	[2284739] Primary debugging flag is qDebug not qCoreDebug so					set qDebug in response to wantDebugging.		11/13/98	[2279281] Define qAllegro in place of qPowerPC && (UNIVERSAL_INTERFACES_VERSION >= 0x0320).		10/23/98	Turn off qCarbon if it's not defined*//*	Note: this is a seperate file to make it easy to mro it and set your own	flags locally according to your preferences.*/#ifndef __CoreSwitches_AC__#define __CoreSwitches_AC__#define qDebugLevelOne_AC  			1#define qDebugLevelTwo_AC			2#define qDebugLevelThree_AC			3#define qDebugLevelFour_AC			4// Quality Level://	By setting qQualityLevel_AC (in your customization of AutoSwitches.h) to one//	of the values below you control which components of the framework are included//	in the application being built.  Certain pre-final components of the framework//	may be marked with a quality tag used in #if tests.  Those components with//	a quality rating below the value set in qQualityLevel_AC will not be compiled//	into the final build.#define qPreAlphaQuality_AC			1#define qAlphaQuality_AC			2#define qBetaQuality_AC				3#define qFinalQuality_AC			4#ifndef qAutoSwitches#	define qAutoSwitches 			1#endif#ifndef qCarbon#	define qCarbon					0#endif// Turn on qNeedsCarbonEvents to build programs that require Carbon Events. // This makes programs more efficient, but they will run only on Mac OS X and // on Mac OS 9 with CarbonLib 1.1 or greater. Currently, C++ framework support // for Carbon Events is experimental, so it is available only if qNeedsCarbonEvents // is on. Eventually, programs built with qCarbon on will use Carbon Events if// they are available, but not require them. #ifndef qNeedsCarbonEvents#	define qNeedsCarbonEvents		0#endif// ===================================================================================// AutoSwitches//// Always pull in AutoSwitches before setting specific switches so that the developer// can override specific settings.  Once AutoSwitches has been pulled in overrides// by the developer can be checked for by testing for the definition of each switch.// ===================================================================================#if qAutoSwitches#	ifndef __AutoSwitches_AC__#		define __AutoSwitches_AC__#		include "AutoSwitches_AC.h"#	endif#endif// ========================================================// Processor and Evnironment Detection// ========================================================// __INTEL__ is defined by CodeWarrior when building for Windows and// _MSC_VER is defined by Visual C++.  Enable the following if you// suspect the wrong environment is being built.#if 0	#ifdef __INTEL__		#pragma message	("__INTEL__ is defined." __FILE__)	#endif		#ifdef _MSC_VER		#pragma message	("_MSC_VER is defined." __FILE__)	#endif#endif// Note that qMSWindows cannot be set in AutoSwitches -- it is set automatically// as a result of environment settings.#if defined(__INTEL__) || defined(_MSC_VER)#	define qMSWindows 1#else#	define qMSWindows 0#endif#ifndef qProjectBuilder	#ifdef __GNUC__		#define qProjectBuilder 1	#else		#define qProjectBuilder 0	#endif#endif// ========================================================// Processor requirements// ========================================================#ifndef qQualityLevel_AC	#define qQualityLevel_AC			qFinalQuality_AC#endif// ========================================================// ••• BIG RED SWITCH FOR DEBUGGING •••// 0=nodebug, 1=debug// This can be overridden in your AutoSwitches_AC.h file by// independently setting qDebug and/or dCoreDebug.// ========================================================#ifndef wantDebugging	#define wantDebugging 			1	#endif#ifndef qDebug#	if wantDebugging#		define qDebug  				1#	else#		define qDebug  				0#	endif#endif#ifndef qCoreDebug#	ifdef qDebug#		define qCoreDebug 			qDebug#	else	#		define qCoreDebug 			0 // default to off#	endif#endif#if qCoreDebug// ACS Flags#	ifndef qDebugExceptions#	define qDebugExceptions 		qDebugLevelFour_AC#	endif// exceptions debugging// Level 1: Catch and Throw messages are compiled out. Still get throw location though.// Level 2: Catch and Throw messages are compiled in, throw message on by default, catch// 			message off by default. Can change runtime switch for enabling disabling//			catch and throw messages.// Level 3: Catch and Throw messages are compiled in, throw message off by default, catch// 			message on by default. Can change runtime switch for enabling disabling//			catch and throw messages.// Level 4: Catch and Throw messages are compiled in, throw message on by default, catch// 			message on by default. Can change runtime switch for enabling disabling//			catch and throw messages#	ifndef qAssertions			#		define qAssertions			1#	endif#	ifndef qTidyHeap#		if qCarbon || qMSWindows#			define qTidyHeap			0#		else	#			define qTidyHeap			1#		endif#	endif#	ifndef qDebugMsg#	define qDebugMsg 				1#	endif#	ifndef qRangeCheck#	define qRangeCheck 				1#	endif#else	// qCoreDebug	#	ifndef qDebugExceptions#		define qDebugExceptions 	0#	endif#	ifndef qAssertions			#		define qAssertions			0#	endif#	ifndef qTidyHeap#		define qTidyHeap			0#	endif#	ifndef qDebugMsg#	define qDebugMsg 				0#	endif#	ifndef qRangeCheck#	define qRangeCheck 				0#	endif#endif	// qCoreDebug#if !defined(qBackwardCompatible)#	define qBackwardCompatible 0// set to true to leave in compatibility sops that will probably be removed// in a subsequent release#endif// qTrainingWheels is for compatibility code that will probably// be moved to qBackwardCompatible status in a later release#ifndef qTrainingWheels#	define qTrainingWheels	1#endif// ========================================================// Processor Specific Flag Settings// ========================================================#if qMSWindows#	define qPowerPC 0#	define q68K 0#	if defined(__INTEL__)#		define MSIPL_WIN32 1		// Required by "Win32 SDK:sys:Types.h"#	endif// Standard MacApp services which are not currently available under Windows.// •••  Reconsider these for each release.#define qWantsThreadManager 0// Theese are the ids for the Windows resource string that is the name of the// application and the document used to load the menu bar, accellerators, icons, etc.// •••  These don't really belong here.#define kAppName 1#define kDocName 2#else#	ifndef qPowerPC#		ifdef __POWERPC__#			if __POWERPC__#				define qPowerPC 1#				define q68K 0#			else#				define qPowerPC 0#				define q68K 1#			endif#		else#			define qPowerPC 0#			define q68K 1#		endif#	else#		define q68K !(qPowerPC)#	endif#	ifdef __CFM68K__#		if __CFM68K__#			define qModelCFM 1#		endif#	endif//__MC68881__ and __MC68020__ are set in the processor pane#	ifdef __MC68881__#		if __MC68881__// Remember: You won't be able to run the resulting app on a PPC if you set this#			define qNeedsFPU 1#		endif#	endif#	ifdef __MC68020__#		if __MC68020__#			define qNeedsMC68020 1#		endif#	endif#	define qMSWindows 0#endif // if qMSWindows// ========================================================// Miscellaneous Switches// ========================================================// This controls whether we try to use the Appearance Manager at all. // Turning the switch on means that the Appearance Manager might be // available, and it's okay to compile code that uses it. Turning the// switch off means there is no way the Appearance Manager will be // available, and we'll just have to get by without it. #ifndef qAppearance#	if qMSWindows		// The Apppearance Manager is not available on Windows. #		define qAppearance 0#	else		// The Appearance Manager might be available. #		define qAppearance 1#	endif#endif// This controls whether the Appearance Manager is required to be // present. Turning it on means that the application requires Mac OS // 7.6.1 with AppearanceLib added, or Mac OS 8, 9, or X which all// come with the Appearance Manager already installed. It means // that the AGA emulated controls are not needed, and that new// controls such as sliders and tab panels may be used. // Turning it off does not necessarily mean that the AGA emulated// controls should be required. The Appearance Manager may be used // if the runtime check (HasAppearanceMgr_AC) shows that it is present. // The standard controls: push buttons, check boxes, radio buttons, // scroll bars, and popup menus will be available no matter what. #ifndef qNeedsAppearance	// If the Appearance Manager may be available at all,	// we're going to require it. #	define qNeedsAppearance qAppearance#endif// This controls whether controls may be emulated using AGA when // the Appearance Manager is not present. Turning it on means the // emulated controls will be available. Normally it should be off // in order to save space and run-time overhead. If the Appearance // Manager is required, there is no need for the emulated controls. // The Appearance Manager is not available on Windows, but the// emulated controls only support the Mac OS 8 look and feel, which // is probably not appropriate. This leaves Mac OS 7.5 and earlier, // and again it probably is more appropriate to use the native look// and feel. If you need a new control such as a slider or a tab// panel, on systems that don't have the Appearance Manager, you// should consider creating a custom control that has the right// look and feel for the target system. #ifndef qEmulateStandardControls#	define qEmulateStandardControls 0#endif// CFile_AC::GetNavFileOrFolderInfo references NavServices routines, so this// switch needs to be set in ACS, as well as MacApp switches.#ifndef qNavigation#	if qMSWindows#		define qNavigation 0#	else#		define qNavigation 1#	endif#endif// ========================================================// Thread Switches// ========================================================/*	This file defines the following switches:		qThreadDebug			Controls whether debugging code is compiled.					If not defined and qCoreDebug is defined, it is defined as qCoreDebug, otherwise 1.		qInstrumentation				Controls wether instrumentation debugging code is compiled.			If building for Windows, it is defined as 0; otherwise if not defined, it is defined as 0.		qWantsMP					Controls whether MP support code is compiled.				If not building for PowerPC, it is defined as 0; otherwise if not defined, it is defined as 1.		qWantsThreadMgr			Controls whether ThreadMgr support code is compiled.			If not defined, it is defined as 1.				qYieldToOtherProcesses			determines whether calls to yield to another thread should also 			provide other processes opportunities to run, using SystemTask.		qMonitorCancel				When supported, this flag will cause the thread supporting yeilds to MP tasks and other			processes to take on the additional role of checking for command-period.  If the main 			thread is blocked waiting on a lock, it will be resumed with an exception.  If the main			thread is otherwise busy, the exception will be thown the next time YieldCPU is called			or an attempt is made to aquire a lock.*/// qThreadDebug#ifndef qThreadDebug#	ifdef qCoreDebug#		define qThreadDebug qCoreDebug #	else#		define qThreadDebug 1#	endif#endif// qInstrumentation#if !qMSWindows#	ifndef qInstrumentation#		define qInstrumentation 0#	endif#else// Can't have instrumentation on Win32#	undef qInstrumentation#	define qInstrumentation 0#endif// qWantsMP#ifdef __POWERPC__#	ifndef qWantsMP#		define qWantsMP 1#	endif#else// Can't have MP on 68K#	undef qWantsMP#	define qWantsMP 0#endif// Define MPIncludeDefunctServices to 1 if qWantsMP so that _MPDebugStr is available.#if qWantsMP#	ifdef MPIncludeDefunctServices#		undef MPIncludeDefunctServices#	endif#	define MPIncludeDefunctServices 1#endif// qWantsThreadMgr#ifndef qWantsThreadManager#	define qWantsThreadManager 1#endif// qYieldToOtherProcesses#ifndef qYieldToOtherProcesses#	define qYieldToOtherProcesses 0#endif// qMonitorCancel#ifndef qMonitorCancel	// Not yet supported.#	define qMonitorCancel 0#endif// ========================================================// Sanity Checks// ========================================================// Don't build in TidyHeap if not PPC, not 68K or building with CodeWarrior and 68K.#if qTidyHeap && (!(qPowerPC || q68K) || (defined(__MWERKS__) &&  q68K))# 	undef qTidyHeap#	define qTidyHeap 0#endif#ifdef __MWERKS__#	if !__option(bool)#	error "bool support must be enabled in order to build ACS and MacApp"#	endif#	if !__option(exceptions)#	error "native C++ exceptions must be enabled in order to build ACS and MacApp"#	endif#endif#endif // __CoreSwitches_AC__